/**
 * Bundle-safe view of the unified library.
 *
 * `lib/data/library.ts` is the authoritative runtime library, but importing it drags the
 * 776 KB `library-candidates.json` into whatever bundle reaches for it. Client UI that only
 * needs the layer breakdown + enrichment queue reads this 7.7 KB projection instead,
 * generated by `scripts/build_library.py` (same run that emits the candidate layer).
 */
import statsRaw from './library-stats.json';
import type { LibraryStatsFile } from '../types';

export const libraryStatsData: LibraryStatsFile = statsRaw as unknown as LibraryStatsFile;

export const LAYER_STATS = libraryStatsData.layers ?? [];
// `library-stats.json` is regenerated from the catalogue, and an earlier version of that generator
// rewrote the file wholesale and dropped these keys — /catalog/ then died on `queue.slice` and
// rendered nothing at all. A missing key must degrade to an empty list, never to a blank page.
export const ENRICHMENT_QUEUE = libraryStatsData.enrichmentQueue ?? [];
export const PM_REQUIRED_FIELDS = libraryStatsData.pmRequiredFields ?? [];

/**
 * Short zh/en label for a stage key emitted by the engine (`lib/matching.ts`).
 *
 * Must cover **every** id the engine emits, or the funnel prints a raw key like
 * `5_high_match_truncation`. `engine_check.ts` asserts the two lists agree, because this table went
 * stale the first time the stage list changed — it had the same hole (`…3, 5…`) the engine did.
 */
export const STAGE_LABELS: Record<string, { zh: string; en: string }> = {
  '1_hard_filter': { zh: '硬性过滤（完整度/状态）', en: 'Hard filter (completeness / status)' },
  '2_semantic_recall': { zh: '语义召回', en: 'Semantic recall' },
  '3_feature_scoring': { zh: '六维适配打分', en: 'Six-dimension fit scoring' },
  '4_opportunity_scoring': { zh: '潜力与机会打分', en: 'Potential & opportunity scoring' },
  '5_high_match_truncation': { zh: '高匹配截断', en: 'High-match truncation' },
  '6_final_score': { zh: '最终推荐分', en: 'Final recommendation score' },
  '7_diversity_rerank': { zh: '多样性重排', en: 'Diversity rerank' },
  '8_curation': { zh: 'Top 5 策展', en: 'Top-5 curation' },
};
